/* ---------- ECG monitor ---------- */
function monitor(canvas,vitEl){
  const ctx=canvas.getContext('2d');let v={hr:88,sp:98,rr:16,bp:'122/78'},x=0,last=0,phase=0,prevY=null;
  const render=()=>{vitEl.innerHTML=`<div class="v-hr"><span>HR</span><b>${v.hr}</b></div><div class="v-sp"><span>SpO₂</span><b>${v.sp}%</b></div><div class="v-rr"><span>RR</span><b>${v.rr}</b></div><div class="v-bp"><span>BP</span><b style="font-size:24px">${v.bp}</b></div>`};
  const size=()=>{const r=canvas.getBoundingClientRect();canvas.width=Math.max(1,r.width*devicePixelRatio);canvas.height=Math.max(1,r.height*devicePixelRatio);ctx.fillStyle='#05080f';ctx.fillRect(0,0,canvas.width,canvas.height);x=0;prevY=null};
  const ro=new ResizeObserver(size);ro.observe(canvas);
  const wave=p=>{ // p 0..1 within beat
    if(p<.1)return Math.sin(p/.1*Math.PI)*.08;
    if(p<.16)return 0;if(p<.18)return -.12;if(p<.21)return 1;if(p<.24)return -.25;if(p<.3)return 0;
    if(p<.45)return Math.sin((p-.3)/.15*Math.PI)*.18;return 0};
  const tick=t=>{
    const dt=Math.min(50,t-(last||t));last=t;const W=canvas.width,H=canvas.height;if(W<2){requestAnimationFrame(tick);return}
    const speed=W/4500; // full sweep in 4.5s
    const steps=Math.max(1,Math.round(dt*speed));
    for(let i=0;i<steps;i++){
      phase+=(v.hr/60)/1000/speed;if(phase>1)phase-=1;
      const y=H*.62-wave(phase)*H*.5;
      ctx.fillStyle='#05080f';ctx.fillRect(x+1,0,14*devicePixelRatio,H);
      ctx.strokeStyle='#3dff8e';ctx.lineWidth=2*devicePixelRatio;ctx.beginPath();ctx.moveTo(x,prevY??y);ctx.lineTo(x+1,y);ctx.stroke();
      prevY=y;x+=1;if(x>=W){x=0;prevY=null}
    }
    if(!RM)requestAnimationFrame(tick);
  };
  render();
  if(RM){setTimeout(()=>{const W=canvas.width,H=canvas.height;ctx.strokeStyle='#3dff8e';ctx.lineWidth=2;ctx.beginPath();for(let i=0;i<W;i++){const y=H*.62-wave((i/W*4)%1)*H*.5;i?ctx.lineTo(i,y):ctx.moveTo(i,y)}ctx.stroke()},100)}else requestAnimationFrame(tick);
  return {set(n){v={...v,...n};render()}};
}

