function miniBronch(){return '<svg viewBox="0 0 240 120" width="100%"><g><circle cx="60" cy="60" r="44" fill="#f4b6bd"/><circle cx="60" cy="60" r="30" fill="var(--card)"/><text x="60" y="114" text-anchor="middle" font-size="14" fill="currentColor">Normal</text></g><g><circle cx="180" cy="60" r="44" fill="#e5707e"/><circle cx="180" cy="60" r="11" fill="var(--card)"/><circle cx="170" cy="52" r="5" fill="#e8d36a"/><circle cx="190" cy="66" r="4" fill="#e8d36a"/><text x="180" y="114" text-anchor="middle" font-size="14" fill="currentColor">Asthma attack</text></g></svg>'}
function miniTri(){return '<svg viewBox="0 0 240 200" width="100%"><path d="M120 20L220 180H20Z" fill="none" stroke="var(--blue)" stroke-width="6" stroke-linejoin="round"/><text x="120" y="14" text-anchor="middle" font-size="18" font-weight="700" fill="currentColor">Pump</text><text x="20" y="198" font-size="18" font-weight="700" fill="currentColor">Pipes</text><text x="220" y="198" text-anchor="end" font-size="18" font-weight="700" fill="currentColor">Fluid</text></svg>'}
const sList=()=>SLIDES.filter(s=>sFilter==='all'||s.t===sFilter);
function renderSlides(){
  $('slideFilter').innerHTML=['all',...Object.keys(TOPIC).filter(k=>SLIDES.some(x=>x.t===k))].map(f=>`<button class="chip ${f===sFilter?'on':''}" data-f="${f}">${f==='all'?'All':esc(TOPIC[f])}</button>`).join('');
  const L=sList();
  $('deck').innerHTML=L.map(s=>`<article class="slide"><div>${tag(s.t)}<h2 style="margin-top:10px">${s.h}</h2><ul>${s.b.map(x=>`<li>${x}</li>`).join('')}</ul>${s.p?`<div class="pearl"><b>Pearl:</b> ${s.p}</div>`:''}${s.ep?`<a href="https://www.youtube.com/watch?v=${s.ep[1]}" target="_blank" rel="noopener" style="display:inline-block;margin-top:12px;color:var(--blue);font-weight:700">▶ Watch Ari Deutsch Ep ${s.ep[0]}: ${s.ep[2]}</a>`:''}</div><div class="art">${artFor(s)}</div></article>`).join('');
  $('sDots').innerHTML=L.map((_,i)=>`<i></i>`).join('');sIdx=0;updDeck();
}
function updDeck(){const L=sList();$('sCount').textContent=(sIdx+1)+' / '+L.length;[...$('sDots').children].forEach((d,i)=>d.classList.toggle('on',i===sIdx));$('sPrev').disabled=sIdx===0;$('sNext').disabled=sIdx===L.length-1;
  const s=L[sIdx];if(s){const k=SLIDES.indexOf(s);if(!seen.has(k)){seen.add(k);S.set('slideSeen',[...seen]);addXP(2)}}}
function goSlide(i){const L=sList();sIdx=Math.max(0,Math.min(L.length-1,i));const el=$('deck').children[sIdx];if(el)$('deck').scrollTo({left:el.offsetLeft-$('deck').offsetLeft,behavior:RM?'auto':'smooth'});updDeck()}
$('slideFilter').addEventListener('click',e=>{const b=e.target.closest('[data-f]');if(b){sFilter=b.dataset.f;renderSlides()}});
$('sPrev').onclick=()=>goSlide(sIdx-1);$('sNext').onclick=()=>goSlide(sIdx+1);
let sT;$('deck').addEventListener('scroll',()=>{clearTimeout(sT);sT=setTimeout(()=>{const d=$('deck');const i=Math.round(d.scrollLeft/(d.clientWidth+16));if(i!==sIdx){sIdx=i;updDeck()}},90)});
addEventListener('keydown',e=>{if(!isOn('slides'))return;if(e.key==='ArrowRight')goSlide(sIdx+1);if(e.key==='ArrowLeft')goSlide(sIdx-1)});
renderSlides();

/* ---------- bronchiole animation ---------- */
const bro=$('bronch');let sev=0,parts=Array.from({length:40},()=>({x:Math.random()*600,y:Math.random()*2-1}));
bro.innerHTML=`<rect x="0" y="0" width="600" height="280" rx="14" fill="var(--soft)"/>
<g id="bTop"><rect id="bTw" x="0" y="20" width="600" height="60" fill="#f2a8b1"/><rect id="bTm" x="0" y="20" width="600" height="12" fill="#b23a4b"/></g>
<g id="bBot"><rect id="bBw" x="0" y="200" width="600" height="60" fill="#f2a8b1"/><rect id="bBm" x="0" y="248" width="600" height="12" fill="#b23a4b"/></g>
<g id="bMuc"></g><g id="bAir"></g>
<text x="12" y="16" font-size="14" font-weight="700" fill="var(--ink)">Smooth muscle</text>
<text x="588" y="276" text-anchor="end" font-size="14" font-weight="700" fill="var(--ink)">Inflamed wall</text>
<text id="bLbl" x="300" y="146" text-anchor="middle" font-size="16" font-weight="700" fill="var(--blue)">Airflow →</text>`;
function updBronch(){const gap=Math.max(14,90-sev*.74),top=140-gap;
  $('bTw').setAttribute('height',top-20);$('bBw').setAttribute('y',140+gap);$('bBw').setAttribute('height',260-(140+gap));
  const m=12+sev*.12;$('bTm').setAttribute('height',m);$('bBm').setAttribute('y',260-m);$('bBm').setAttribute('height',m);
  const mc=Math.round(sev/12);let s='';for(let i=0;i<mc;i++){const x=40+i*68;s+=`<ellipse cx="${x}" cy="${top+4}" rx="${14+sev/10}" ry="${5+sev/20}" fill="#e8d36a" opacity=".9"/><ellipse cx="${x+34}" cy="${140+gap-4}" rx="${12+sev/10}" ry="${5+sev/20}" fill="#e8d36a" opacity=".9"/>`}
  $('bMuc').innerHTML=s;$('bLbl').style.opacity=sev>70?0:1;
  $('sevTxt').textContent=sev<15?'Normal airway: wide open, air moves freely.':sev<45?'Mild: walls swelling, muscle starting to tighten. Cough, mild dyspnea.':sev<75?'Moderate to severe: narrow lumen, mucus plugs. Wheezing, tripod, 2–3 word dyspnea.':sev<92?'Severe: very little air moves. Hypoxia, cyanosis, tiring out.':'Critical: silent chest. Almost no airflow. Prepare to ventilate.';
  return gap}
let gapNow=updBronch();
$('sev').addEventListener('input',e=>{sev=+e.target.value;gapNow=updBronch()});
function airTick(){const sp=Math.pow(gapNow/90,2)*4+.15;$('bAir').innerHTML=parts.map(p=>{p.x+=sp;if(p.x>600)p.x=0;const y=140+p.y*(gapNow-8);return `<circle cx="${p.x.toFixed(1)}" cy="${y.toFixed(1)}" r="4" fill="var(--blue)" opacity=".7"/>`}).join('');if(!RM)requestAnimationFrame(airTick)}
airTick();

/* ---------- perfusion triangle ---------- */
const broken={pump:false,pipes:false,fluid:false};let triA=0;
const triInfo={pump:'Pump failure → cardiogenic shock (e.g. heart attack). Obstructive shock also stops the pump: tension pneumothorax, tamponade, PE.',pipes:'Pipe failure → distributive shock: septic, neurogenic, anaphylactic, psychogenic.',fluid:'Fluid failure → hypovolemic shock: hemorrhage, dehydration, burns.'};
$('triBtns').innerHTML=['pump','pipes','fluid'].map(k=>`<button class="chip" data-k="${k}">Break the ${k}</button>`).join('')+'<button class="chip" data-k="reset">Reset</button>';
$('triBtns').addEventListener('click',e=>{const b=e.target.closest('[data-k]');if(!b)return;const k=b.dataset.k;if(k==='reset'){for(const x in broken)broken[x]=false}else broken[k]=!broken[k];
  [...$('triBtns').children].forEach(c=>c.classList.toggle('on',!!broken[c.dataset.k]));drawTri()});
const P=[[250,40],[440,260],[60,260]];
function drawTri(){const bad=Object.keys(broken).filter(k=>broken[k]);
  const col=k=>broken[k]?'var(--red)':'var(--blue)';
  $('tri').innerHTML=`<path d="M${P[0]}L${P[1]}" stroke="${col('pump')}" stroke-width="10" stroke-linecap="round" ${broken.pump?'stroke-dasharray="14 12"':''}/>
  <path d="M${P[1]}L${P[2]}" stroke="${col('fluid')}" stroke-width="10" stroke-linecap="round" ${broken.fluid?'stroke-dasharray="14 12"':''}/>
  <path d="M${P[2]}L${P[0]}" stroke="${col('pipes')}" stroke-width="10" stroke-linecap="round" ${broken.pipes?'stroke-dasharray="14 12"':''}/>
  <g transform="translate(250 40)"><path d="M0 18C-30-6-22-30 0-16C22-30 30-6 0 18Z" fill="${col('pump')}"/></g>
  <text x="250" y="88" text-anchor="middle" font-weight="700" font-size="17" fill="var(--ink)">Pump · heart</text>
  <text x="96" y="160" text-anchor="end" font-weight="700" font-size="17" fill="var(--ink)">Pipes</text><text x="96" y="180" text-anchor="end" font-size="14" fill="var(--mute)">vessels</text>
  <text x="404" y="160" font-weight="700" font-size="17" fill="var(--ink)">Fluid</text><text x="404" y="180" font-size="14" fill="var(--mute)">blood</text>
  <circle id="triDot" r="11" fill="var(--red)"/>`;
  $('triTxt').textContent=bad.length===0?'All three sides working: perfusion is adequate.':bad.map(k=>triInfo[k]).join(' ');
}
function triTick(){const d=$('triDot');if(d){const bad=Object.values(broken).filter(Boolean).length;triA=(triA+(bad?0.0012/(bad*2):0.004))%1;const seg=Math.floor(triA*3),f=triA*3-seg,a=P[seg],b=P[(seg+1)%3];d.setAttribute('cx',a[0]+(b[0]-a[0])*f);d.setAttribute('cy',a[1]+(b[1]-a[1])*f);d.setAttribute('opacity',bad?.45:1)}if(!RM)requestAnimationFrame(triTick)}
drawTri();triTick();

/* ---------- OPA animation ---------- */
let opaKid=false,opaStep=0;
$('opa').innerHTML=`<rect width="520" height="300" rx="14" fill="var(--soft)"/>
<path d="M60 40C200 20 330 40 400 110L400 300" fill="none" stroke="#c98b74" stroke-width="22" stroke-linecap="round"/>
<text x="230" y="22" text-anchor="middle" font-size="14" font-weight="700" fill="var(--ink)">Palate (roof of mouth)</text>
<path d="M130 230C150 150 300 140 340 220Z" fill="#e5707e"/><text x="235" y="215" text-anchor="middle" font-size="14" font-weight="700" fill="#fff">Tongue</text>
<text x="428" y="200" font-size="14" font-weight="700" fill="var(--ink)">Pharynx</text>
<rect x="100" y="110" width="8" height="100" rx="4" fill="#c98b74"/><text x="104" y="102" text-anchor="middle" font-size="14" font-weight="700" fill="var(--ink)">Lips</text>
<g id="depr" style="opacity:0;transition:opacity .5s"><rect x="110" y="196" width="200" height="10" rx="5" fill="#d9c08a"/></g>
<g id="opaG" style="transition:transform 1s ease-in-out"><path d="M0 -22V22" stroke="var(--ink)" stroke-width="10" stroke-linecap="round"/><path d="M0 0C110 0 220 0 280 110" fill="none" stroke="var(--blue)" stroke-width="16" stroke-linecap="round"/></g>`;
const opaG=$('opaG');
const OPA={adult:[['translate(-120px,150px)','Measure: corner of mouth to earlobe. Patient must be unresponsive with no gag reflex.'],['translate(30px,150px) scale(0.85,-0.85)','Insert upside down, tip toward the roof of the mouth, so it slides over the tongue.'],['translate(104px,150px) scale(0.85,0.85)','At the back of the tongue, rotate 180°. The curve now follows the tongue into the pharynx.'],['translate(104px,150px) scale(0.85,0.85)','Done: flange flush on the lips. Gag at any point → remove it.']],
kid:[['translate(-120px,150px)','Measure: corner of mouth to earlobe. Unresponsive, no gag reflex.'],['translate(-40px,150px) scale(0.85,0.85)','Press the tongue down and forward with a tongue depressor.'],['translate(104px,150px) scale(0.85,0.85)','Insert straight in, already curved toward the tongue. No rotation: protects the soft palate.'],['translate(104px,150px) scale(0.85,0.85)','Done: flange flush on the lips.']]};
function showOpa(){const L=opaKid?OPA.kid:OPA.adult;const [tr,txt]=L[opaStep];opaG.style.transform=tr;$('depr').style.opacity=opaKid&&opaStep>0?1:0;$('opaTxt').textContent=`Step ${opaStep+1} of 4: ${txt}`;$('opaStep').textContent=opaStep===3?'Start over':'Next step'}
$('opaStep').onclick=()=>{opaStep=(opaStep+1)%4;showOpa();if(opaStep===3)addXP(3)};
$('opaAdult').onclick=()=>{opaKid=false;opaStep=0;$('opaAdult').classList.add('on');$('opaKid').classList.remove('on');showOpa()};
$('opaKid').onclick=()=>{opaKid=true;opaStep=0;$('opaKid').classList.add('on');$('opaAdult').classList.remove('on');showOpa()};
showOpa();

/* ---------- CPR metronome ---------- */
let cprOn=false,cprT=null,comp=0,br=0,snd=false,actx=null,t0=0;
const beep=(f,d)=>{if(!snd)return;try{actx=actx||new (window.AudioContext||window.webkitAudioContext)();const o=actx.createOscillator(),g=actx.createGain();o.frequency.value=f;g.gain.value=.15;o.connect(g);g.connect(actx.destination);o.start();o.stop(actx.currentTime+d)}catch(e){}};
$('cprSnd').onclick=()=>{snd=!snd;$('cprSnd').textContent='Sound: '+(snd?'on':'off');$('cprSnd').classList.toggle('on',snd);if(snd)beep(660,.05)};
$('cprGo').onclick=()=>{cprOn=!cprOn;$('cprGo').textContent=cprOn?'Stop':'Start';
  if(cprOn){comp=0;br=0;t0=Date.now();let lastBreath=0;cprT=setInterval(()=>{comp++;const el=$('pulse');const el2=Date.now()-t0;
    if(el2-lastBreath>=6000){lastBreath=el2;br++;el.classList.add('breathe');el.textContent='Breathe';beep(440,.25);setTimeout(()=>el.classList.remove('breathe'),700)}
    else if(!el.classList.contains('breathe')){el.textContent=comp;beep(880,.03)}
    el.style.transform='scale(.9)';setTimeout(()=>el.style.transform='',120);
    $('cprTxt').textContent=`Compressions: ${comp} · Breaths: ${br} · ${Math.floor(el2/1000)} s`},545)}
  else{clearInterval(cprT);$('pulse').textContent='Ready';if(comp>50)addXP(5)}};

/* ---------- games ---------- */
const GAMES=[['assess','Assessment Builder'],['mnem','Mnemonic Decoder'],['detective','Shock Detective'],['builder','Airway Builder'],['speed','Speed Round'],['sim','Patient Sim']];
let gameNow='assess',spT=null;
$('gameTabs').innerHTML=GAMES.map(([k,l])=>`<button class="chip ${k===gameNow?'on':''}" data-g="${k}">${l}</button>`).join('');
$('gameTabs').onclick=e=>{const b=e.target.closest('[data-g]');if(!b)return;gameNow=b.dataset.g;[...$('gameTabs').children].forEach(c=>c.classList.toggle('on',c===b));runGame()};
function runGame(){clearInterval(spT);({assess:()=>gBuilder(ORDER2,'Build the medical assessment','Tap the steps of a medical patient assessment in order, from arrival to handoff.'),mnem:gMnem,detective:gDetective,builder:()=>gBuilder(ORDER,'Build the airway sequence','Tap the steps in the right order for an unresponsive patient with fluid in the mouth and inadequate breathing.'),speed:gSpeed,sim:gSimMenu})[gameNow]()}

function gDetective(){let L=shuffle(CASES),i=0,sc=0,streak=0;
  const show=()=>{if(i>=L.length){recordGame('detective',100*sc/L.length);$('game').innerHTML=`<div class="card" style="max-width:720px"><h3>Case files closed</h3><div class="big">${sc}/${L.length}</div><button class="btn" id="dAgain">Play again</button></div>`;$('dAgain').onclick=gDetective;addXP(sc*2);return}
    const c=L[i];$('game').innerHTML=`<div class="card" style="max-width:760px"><div style="display:flex;justify-content:space-between"><b>Case ${i+1} of ${L.length}</b><span class="mute">Score ${sc} · Streak ${streak}</span></div>
    <h3 style="margin-top:12px">${c.s}</h3><p class="mute">What type of shock?</p><div class="pool" id="dOpts">${TYPES.map(t=>`<button class="btn alt" data-t="${t}">${t}</button>`).join('')}</div><div id="dFb" style="margin-top:12px"></div></div>`;
    $('dOpts').onclick=e=>{const b=e.target.closest('[data-t]');if(!b||b.disabled)return;const ok=b.dataset.t===c.a;[...$('dOpts').children].forEach(x=>{x.disabled=true;if(x.dataset.t===c.a){x.style.background='var(--ok)';x.style.color='#fff'}});
      if(ok){sc++;streak++}else{streak=0;b.style.background='#c2414f';b.style.color='#fff'}
      $('dFb').innerHTML=`<div class="expl"><b>${ok?'Solved.':c.a+'.'}</b> ${c.e}</div><button class="btn" id="dNext">Next case</button>`;$('dNext').onclick=()=>{i++;show()}}};
  show()}

function gBuilder(ORDER,title,desc){const again=()=>gBuilder(ORDER,title,desc);const pool=shuffle(ORDER.map((s,i)=>i));let got=0,miss=0,start=Date.now();
  const draw=()=>{$('game').innerHTML=`<div class="card" style="max-width:760px"><h3>${title}</h3><p class="mute">${desc} Misses: ${miss}</p>
    <div class="order-list">${ORDER.slice(0,got).map((s,i)=>`<div class="step"><b>${i+1}</b>${s}</div>`).join('')}</div>
    ${got<ORDER.length?`<div class="pool" id="bPool">${pool.filter(i=>i>=got).map(i=>`<button class="btn alt" data-i="${i}">${ORDER[i]}</button>`).join('')}</div>`:`<div class="expl"><b>Sequence complete</b> in ${Math.round((Date.now()-start)/1000)} s with ${miss} misses.</div><button class="btn" id="bAgain">Play again</button>`}</div>`;
    if($('bAgain')){$('bAgain').onclick=again;addXP(Math.max(4,15-miss*2));recordGame(ORDER.length>10?'builder-assess':'builder-airway',100-miss*100/ORDER.length);return}
    $('bPool').onclick=e=>{const b=e.target.closest('[data-i]');if(!b)return;if(+b.dataset.i===got){got++;draw()}else{miss++;b.classList.remove('shake');void b.offsetWidth;b.classList.add('shake');b.closest('.card').querySelector('.mute').textContent='Not yet. Misses: '+miss}}};
  draw()}

function gSpeed(){$('game').innerHTML=`<div class="card" style="max-width:640px;text-align:center"><h3>Speed Round</h3><p>60 seconds. True or false. +1 right, −1 wrong.</p><p class="mute">Best: ${S.get('spbest',0)}</p><button class="btn red" id="spGo">Go!</button></div>`;
  $('spGo').onclick=()=>{let L=shuffle(TF),i=0,sc=0,left=60;
    const show=()=>{const s=L[i%L.length];$('game').innerHTML=`<div class="card" style="max-width:640px;text-align:center"><div class="timer" id="spT">${left}</div><p class="mute">Score <b id="spS">${sc}</b></p><h3 style="min-height:2.2em">${s[0]}</h3><div class="chips" style="justify-content:center"><button class="btn" style="background:var(--ok);min-width:120px" data-a="1">True</button><button class="btn red" style="min-width:120px" data-a="0">False</button></div><p id="spFb" style="font-weight:600;min-height:1.5em"></p></div>`;
      $('game').querySelector('.chips').onclick=e=>{const b=e.target.closest('[data-a]');if(!b)return;const ok=+b.dataset.a===s[1];sc+=ok?1:-1;i++;show();$('spFb').textContent=ok?'✓ Right':'✗ That was '+(s[1]?'true':'false');$('spFb').style.color=ok?'var(--ok)':'var(--red)'}};
    show();spT=setInterval(()=>{left--;const t=$('spT');if(t)t.textContent=left;if(left<=0){clearInterval(spT);if(sc>S.get('spbest',0))S.set('spbest',sc);addXP(Math.max(0,sc));$('game').innerHTML=`<div class="card" style="max-width:640px;text-align:center"><h3>Time!</h3><div class="big">${sc}</div><p>Best: ${S.get('spbest',0)}</p><button class="btn red" id="spAgain">Again</button></div>`;$('spAgain').onclick=gSpeed}},1000)}}

function gMnem(){const qs=[];for(const k in MNEM)MNEM[k].forEach(([l,m],i)=>qs.push({k,l,m,i}));const L=shuffle(qs).slice(0,12);let i=0,sc=0;
  const all=[...new Set(qs.map(q=>q.m))];
  const show=()=>{if(i>=L.length){recordGame('mnem',100*sc/L.length);addXP(sc*2);$('game').innerHTML=`<div class="card" style="max-width:640px;text-align:center"><h3>Decoded</h3><div class="big">${sc}/${L.length}</div><button class="btn" id="mAgain">Play again</button></div>`;$('mAgain').onclick=gMnem;return}
    const q=L[i];const opts=shuffle([q.m,...shuffle(all.filter(m=>m!==q.m)).slice(0,3)]);
    const word=MNEM[q.k].map((x,j)=>j===q.i?`<span style="color:var(--red);text-decoration:underline">${x[0]}</span>`:x[0]).join(q.k==='BE FAST'&&false?'':' ');
    $('game').innerHTML=`<div class="card" style="max-width:640px"><div style="display:flex;justify-content:space-between"><b>${i+1} of ${L.length}</b><span class="mute">Score ${sc}</span></div><p class="mute" style="margin-top:10px">${q.k}</p><div class="big" style="letter-spacing:.08em">${word}</div><p>What does the highlighted <b>${q.l}</b> stand for?</p><div class="q-opts" id="mO">${opts.map(o=>`<button class="opt">${o}</button>`).join('')}</div><div id="mFb"></div></div>`;
    $('mO').onclick=e=>{const b=e.target.closest('.opt');if(!b||b.disabled)return;const ok=b.textContent===q.m;[...$('mO').children].forEach(o=>{o.disabled=true;if(o.textContent===q.m)o.classList.add('right')});if(ok)sc++;else b.classList.add('wrong');
      $('mFb').innerHTML=`<button class="btn" id="mNext">Next</button>`;$('mNext').onclick=()=>{i++;show()};$('mNext').focus()}};
  show()}

function gSimMenu(){$('game').innerHTML=`<div class="grid">${SIMS.map((s,i)=>`<div class="card"><h3>${s.name}</h3><p class="mute">${s.intro}</p><button class="btn red" data-s="${i}">Respond</button></div>`).join('')}</div>`;
  $('game').onclick=e=>{const b=e.target.closest('[data-s]');if(b){$('game').onclick=null;gSim(SIMS[+b.dataset.s])}}}
function gSim(sim){let st=0,score=0,log=[];
  $('game').innerHTML=`<div class="sim"><div class="monitor"><div class="mon-screen"><canvas id="simEcg"></canvas><div class="vit" id="simVit"></div></div></div><div class="card" id="simCard"></div></div>`;
  const mon=monitor($('simEcg'),$('simVit'));mon.set(sim.v);
  const show=()=>{const card=$('simCard');
    if(st>=sim.steps.length){const pct=score/sim.steps.length;recordGame(sim.name.startsWith('Asthma')?'sim-asthma':sim.name.startsWith('Trauma')?'sim-shock':'sim-ams',100*pct);S.set('sims',S.get('sims',0)+1);addXP(score*5);
      card.innerHTML=`<h3>Patient handed off</h3><div class="big">${score}/${sim.steps.length}</div><p>${pct===1?'Flawless call. Your partner wants you on every shift.':pct>=.6?'Good call with a couple of misses. Review the log.':'Rough shift. Read the feedback and run it again.'}</p><div class="log">${log.join('')}</div><div class="chips" style="margin-top:12px"><button class="btn" id="simAgain">Run again</button><button class="btn alt" id="simMenu">Other call</button></div>`;
      $('simAgain').onclick=()=>gSim(sim);$('simMenu').onclick=gSimMenu;return}
    const s=sim.steps[st];
    card.innerHTML=`<span class="tag">${sim.name} · step ${st+1}/${sim.steps.length}</span>${st===0?`<p class="mute" style="margin-top:8px">${sim.intro}</p>`:''}<h3 style="margin-top:10px">${s.q}</h3><div class="q-opts">${shuffle(s.c.map((c,i)=>i)).map(i=>`<button class="opt" data-i="${i}">${s.c[i][0]}</button>`).join('')}</div><div id="simFb"></div><div class="log">${log.join('')}</div>`;
    card.querySelector('.q-opts').onclick=e=>{const b=e.target.closest('.opt');if(!b||b.disabled)return;const c=s.c[+b.dataset.i];
      card.querySelectorAll('.opt').forEach(o=>{o.disabled=true;if(s.c[+o.dataset.i][1])o.classList.add('right')});
      if(c[1]){score++;mon.set(s.good)}else{b.classList.add('wrong');mon.set(s.bad)}
      if(st===sim.steps.length-1&&sim.name.includes('shock'))mon.set({bp:c[1]?'96/64':'78/50'});
      log.unshift(`<p>${c[1]?'✓':'✗'} ${c[2]}</p>`);
      $('simFb').innerHTML=`<div class="expl"><b>${c[1]?'Good call.':'Partner\'s note:'}</b> ${c[2]}</div><button class="btn" id="simNext">Continue</button>`;$('simNext').onclick=()=>{st++;show()}}};
  if(sim.name.includes('shock'))setTimeout(()=>{},0);
  show()}
runGame();

/* ---------- O2 calculator ---------- */
function o2(){const c=+$('tank').value,p=+$('psi').value||0,l=+$('lpm').value;const m=Math.max(0,(p-200)*c/l);
  $('o2min').textContent=m.toFixed(1);$('o2how').textContent=`(${p} − 200) × ${c} ÷ ${l} = ${m.toFixed(1)} min. The 200 psi is the safe residual you never use.`}
['tank','psi','lpm'].forEach(id=>$(id).addEventListener('input',o2));o2();

