const setZ=()=>{nb.style.setProperty('--nz',nz);S.set('nz',nz)};setZ();
$('nSmall').onclick=()=>{nz=Math.max(.85,+(nz-.1).toFixed(2));setZ()};
$('nBig').onclick=()=>{nz=Math.min(1.6,+(nz+.1).toFixed(2));setZ()};
document.querySelector('.notes-toc').onclick=e=>{const a=e.target.closest('[data-n]');if(!a)return;e.preventDefault();$(a.dataset.n).scrollIntoView({behavior:RM?'auto':'smooth'})};
$('nSearch').addEventListener('input',e=>{const q=e.target.value.trim();nb.innerHTML=orig;if(q.length<2){$('nCount').textContent='';return}
  const re=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');let n=0;
  const walk=node=>{for(const c of [...node.childNodes]){if(c.nodeType===3){if(re.test(c.nodeValue)){re.lastIndex=0;const span=document.createElement('span');span.innerHTML=c.nodeValue.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(re,m=>{n++;return '<mark>'+m+'</mark>'});c.replaceWith(span)}re.lastIndex=0}else walk(c)}};
  walk(nb);$('nCount').textContent=n?`${n} match${n>1?'es':''}`:'No matches';const f=nb.querySelector('mark');if(f)f.scrollIntoView({block:'center'})});
$('copyNotes').onclick=async()=>{try{await navigator.clipboard.writeText(nb.innerText);$('copyNotes').textContent='Copied'}catch(e){$('copyNotes').textContent='Copy blocked'}setTimeout(()=>$('copyNotes').textContent='Copy notes',2000)};

/* ---------- Mastery tracker: running status per chapter from every kind of practice ---------- */
const GAME_CH={detective:13,'builder-assess':10,'builder-airway':11,mnem:10,'sim-asthma':16,'sim-shock':13,'sim-ams':10};
const GAME_NAME={detective:'Shock Detective','builder-assess':'Assessment Builder','builder-airway':'Airway Builder',mnem:'Mnemonic Decoder','sim-asthma':'Asthma sim','sim-shock':'Trauma shock sim','sim-ams':'Altered mental status sim',hebrew:'Hebrew match game'};
function recordGame(key,pct){const g=S.get('games',{});const p=Math.round(Math.max(0,Math.min(100,pct)));const o=g[key]||{best:0,plays:0};g[key]={best:Math.max(o.best,p),last:p,plays:o.plays+1,at:Date.now()};S.set('games',g)}
const STATUS={pat:['Down pat','#1f9d6a','#e7f8ed'],close:['Getting there','#b46205','#fff4e3'],review:['Needs review','#c2414f','#fff0f2'],none:['Not started','#66758a','#eef2f6']};
function chapterMastery(c){
  const n=c.n,att=state.attempts.filter(a=>a.n===n),recent=att.slice(-12),prev=att.slice(-24,-12);
  const acc=rows=>rows.length?Math.round(100*rows.filter(r=>r.correct).length/rows.length):null;
  const quiz=acc(recent),prevQ=acc(prev);
  const deckC=DATA.cards.filter(x=>x[0]===n),known=deckC.filter(x=>state.known.includes(cardId(x))).length;
  const cardsPct=deckC.length?Math.round(100*known/deckC.length):null;
  const read=state.read.includes(n);
  const g=S.get('games',{}),games=Object.entries(GAME_CH).filter(([k,ch])=>ch===n&&g[k]).map(([k])=>({k,...g[k]}));
  const gamePct=games.length?Math.round(games.reduce((s,x)=>s+(x.last*.6+x.best*.4),0)/games.length):null;
  const parts=[];if(quiz!==null)parts.push([quiz,recent.length>=5?.55:.3]);if(cardsPct!==null&&known)parts.push([cardsPct,.2]);if(gamePct!==null)parts.push([gamePct,.2]);if(read)parts.push([100,.05]);
  const any=att.length||known||games.length||read;
  const w=parts.reduce((s,p)=>s+p[1],0);let score=any&&w?Math.round(parts.reduce((s,p)=>s+p[0]*p[1],0)/w):null;
  if(score!==null&&!att.length&&!games.length)score=Math.min(score,40);
  const recentMiss=recent.slice(-3).filter(r=>!r.correct).length>=2;
  let st='none';if(any){st=!att.length&&!games.length?'close':score>=80&&att.length>=8&&quiz>=80&&!recentMiss?'pat':score>=60&&!recentMiss?'close':'review'}
  const ov=S.get('masteryOverride',{})[n];const manual=!!ov;if(ov)st=ov;
  const topics={};att.forEach(a=>{const t=topics[a.topic]||(topics[a.topic]={r:[]});t.r.push(a.correct)});
  const topicRows=Object.entries(topics).map(([t,o])=>{const last=o.r.slice(-6);const p=Math.round(100*last.filter(Boolean).length/last.length);return {t,p,total:o.r.length,st:o.r.length>=3&&p>=80?'pat':p>=60?'close':'review'}}).sort((a,b)=>a.p-b.p);
  const allTopics=new Set(allQuestions.filter(q=>q.n===n).map(q=>q.topic));
  const trend=quiz!==null&&prevQ!==null?quiz-prevQ:null;
  const lastAt=Math.max(0,...att.map(a=>a.at||0),...games.map(x=>x.at||0));
  return {c,score,st,manual,quiz,attempts:att.length,known,deck:deckC.length,cardsPct,read,games,topicRows,untouched:[...allTopics].filter(t=>!topics[t]).length,trend,lastAt};
}
function hebrewMastery(){const g=S.get('games',{}).hebrew;if(!g)return null;return {score:g.last*.6+g.best*.4,st:g.best>=80&&g.plays>=2?'pat':g.best>=60?'close':'review',g}}
const ago=t=>{if(!t)return '';const d=Math.round((Date.now()-t)/864e5);return d<=0?'today':d===1?'yesterday':d+' days ago'};
let mFilter='all';
function renderMastery(){
  const rows=DATA.chapters.map(chapterMastery);const cnt={pat:0,close:0,review:0,none:0};rows.forEach(r=>cnt[r.st]++);
  const started=rows.filter(r=>r.st!=='none');const overall=started.length?Math.round(started.reduce((s,r)=>s+(r.score||0),0)/started.length):null;
  const focus=rows.filter(r=>r.st==='review'||r.st==='close').sort((a,b)=>(a.score??0)-(b.score??0)).slice(0,3);
  const weakT=rows.flatMap(r=>r.topicRows.filter(t=>t.st==='review').map(t=>({...t,n:r.c.n}))).slice(0,6);
  const pill=(st,manual)=>`<span class="m-pill" style="color:${STATUS[st][1]};background:${STATUS[st][2]}">${STATUS[st][0]}${manual?' · set by you':''}</span>`;
  const heb=hebrewMastery();
  $('mSummary').innerHTML=`<div class="m-sum"><span>OVERALL MASTERY</span><strong>${overall===null?'—':overall+'%'}</strong><small>${started.length} of ${rows.length} chapters started</small></div>`+['pat','close','review','none'].map(k=>`<button class="m-sum m-sum-btn ${mFilter===k?'on':''}" data-mf="${k}" style="--c:${STATUS[k][1]}"><span>${STATUS[k][0].toUpperCase()}</span><strong>${cnt[k]}</strong><small>${k==='none'?'chapters to begin':'chapters'}</small></button>`).join('');
  $('mFocus').innerHTML=focus.length||weakT.length?`<div class="card m-focus"><h3>What to work on next</h3>${focus.map(r=>`<div class="m-next"><div><b>Ch ${r.c.n} · ${esc(r.c.title)}</b><span>${r.score??0}% mastery · ${r.quiz===null?'no quiz answers yet':'recent quiz '+r.quiz+'%'}</span></div><div class="m-acts"><a class="btn" href="#quiz/${r.c.n}">Practice</a><a class="btn ghost" href="#chapter/${r.c.n}">Review lesson</a></div></div>`).join('')}${weakT.length?`<p class="mute" style="margin:14px 0 6px">Weak topics</p><div class="chips">${weakT.map(t=>`<a class="chip" href="#quiz/${t.n}">Ch ${t.n} · ${esc(t.t)} · ${t.p}%</a>`).join('')}</div>`:''}</div>`:`<div class="card m-focus"><h3>What to work on next</h3><p style="margin:0">${started.length?'Nothing flagged. Keep practicing to move chapters to <b>Down pat</b>.':'Answer a few quiz questions, flip some flashcards or play a game, and your map fills in automatically.'}</p></div>`;
  const list=rows.filter(r=>mFilter==='all'||r.st===mFilter);
  $('mList').innerHTML=(mFilter!=='all'?`<p class="mute">Showing ${STATUS[mFilter][0].toLowerCase()} · <button class="m-link" data-mf="all">show all</button></p>`:'')+list.map(r=>`<details class="card m-row" style="--c:${STATUS[r.st][1]}">
  <summary><div class="m-head"><div class="m-title"><span class="eyebrow">CHAPTER ${r.c.n} · ${esc(r.c.category)}</span><b>${esc(r.c.title)}</b></div>${pill(r.st,r.manual)}</div>
  <div class="m-barrow"><div class="m-bar"><i style="width:${r.score||0}%;background:${STATUS[r.st][1]}"></i></div><span class="m-score">${r.score===null?'—':r.score+'%'}</span>${r.trend!==null&&Math.abs(r.trend)>=5?`<span class="m-trend" style="color:${r.trend>0?'#1f9d6a':'#c2414f'}">${r.trend>0?'▲':'▼'} ${Math.abs(r.trend)}</span>`:''}</div>
  <div class="m-ev">${[r.attempts?`Quiz ${r.quiz}% recent · ${r.attempts} answers`:'No quiz answers',r.deck?`Cards ${r.known}/${r.deck}`:'',r.read?'Lesson reviewed':'Lesson not marked reviewed',...r.games.map(x=>`${GAME_NAME[x.k]} best ${x.best}%`),r.lastAt?'Last practiced '+ago(r.lastAt):''].filter(Boolean).map(esc).join(' · ')}</div></summary>
  <div class="m-body">${r.topicRows.length?`<h4>Topics</h4><div class="m-topics">${r.topicRows.map(t=>`<div class="m-topic"><span>${esc(t.t)}</span><span class="m-tbar"><i style="width:${t.p}%;background:${STATUS[t.st][1]}"></i></span><span class="m-tp">${t.p}% · ${t.total}</span></div>`).join('')}</div>`:''}${r.untouched?`<p class="mute">${r.untouched} topic${r.untouched>1?'s':''} in this chapter not practiced yet.</p>`:''}
  <div class="m-acts"><a class="btn" href="#quiz/${r.c.n}">Practice Ch ${r.c.n}</a><a class="btn ghost" href="#cards/${r.c.n}">Flashcards</a><a class="btn ghost" href="#chapter/${r.c.n}">Lesson</a></div>
  <div class="m-ovr"><span>How do you feel about it?</span>${[['','Use my results'],['pat','I have it down'],['review','I need review']].map(([v,l])=>`<button class="chip ${(S.get('masteryOverride',{})[r.c.n]||'')===v?'on':''}" data-mo="${r.c.n}" data-mv="${v}">${l}</button>`).join('')}</div></div></details>`).join('')+
  (mFilter==='all'||(heb&&heb.st===mFilter)?`<div class="card m-row m-flat" style="--c:${heb?STATUS[heb.st][1]:STATUS.none[1]}"><div class="m-head"><div class="m-title"><span class="eyebrow">LANGUAGE</span><b>Hebrew EMT terms</b></div>${pill(heb?heb.st:'none')}</div><div class="m-ev">${heb?`Match game best ${heb.g.best}% · last ${heb.g.last}% · ${heb.g.plays} plays`:'Play the Hebrew match game to track this.'} · <a href="#hebrew">Practice Hebrew</a></div></div>`:'');
}
$('v-mastery').addEventListener('click',e=>{const f=e.target.closest('[data-mf]');if(f){mFilter=mFilter===f.dataset.mf?'all':f.dataset.mf;renderMastery();return}
  const o=e.target.closest('[data-mo]');if(o){e.preventDefault();const m=S.get('masteryOverride',{});if(o.dataset.mv)m[o.dataset.mo]=o.dataset.mv;else delete m[o.dataset.mo];S.set('masteryOverride',m);const open=[...document.querySelectorAll('.m-row[open]')].map(d=>d.querySelector('.eyebrow').textContent);renderMastery();document.querySelectorAll('.m-row').forEach(d=>{const ey=d.querySelector('.eyebrow');if(ey&&open.includes(ey.textContent))d.open=true})}});
function masteryMini(){const rows=DATA.chapters.map(chapterMastery);const c={pat:0,close:0,review:0};rows.forEach(r=>{if(c[r.st]!==undefined)c[r.st]++});return c}

