let tourI=-1,tourPrevFocus=null;
const tEl=$('tour'),spot=$('tourSpot');
function placeSpot(){const t=TOUR[tourI];const el=t&&t.sel?document.querySelector(t.sel):null;
  if(!el||!el.getClientRects().length||(el.offsetParent===null&&getComputedStyle(el).position!=='fixed')){spot.style.display='none';tEl.classList.add('dim');return}
  tEl.classList.remove('dim');const r=el.getBoundingClientRect(),pad=6;spot.style.display='block';
  Object.assign(spot.style,{left:(r.left-pad)+'px',top:(r.top-pad)+'px',width:(r.width+pad*2)+'px',height:Math.min(r.height+pad*2,innerHeight*.6)+'px'})}
function tourShow(i){tourI=i;const t=TOUR[i];
  if(t.v!=='notes'&&focusOpen)closeFocus();
  if(('#'+t.v)!==(location.hash||'#home'))location.hash=t.v;
  setTimeout(()=>{const el=t.sel&&document.querySelector(t.sel);if(el&&!el.closest('#focus')&&!el.closest('.sidebar')&&!el.closest('.topbar'))el.scrollIntoView({block:'center',behavior:'auto'});
    $('tourStep').textContent=`Step ${i+1} of ${TOUR.length}`;$('tourH').textContent=t.h;$('tourP').textContent=t.p;
    $('tourBack').disabled=i===0;$('tourNext').textContent=i===TOUR.length-1?'Finish':'Next';
    $('tourDots').innerHTML=TOUR.map((_,j)=>`<i class="${j===i?'on':''}"></i>`).join('');placeSpot();$('tourNext').focus()},160)}
function tourStart(){tourPrevFocus=document.activeElement;tEl.hidden=false;tourShow(0)}
function tourEnd(){tEl.hidden=true;tourI=-1;S.set('toured',1);if(focusOpen)closeFocus();if(location.hash==='#notes')location.hash='home';addXP(10);(tourPrevFocus&&tourPrevFocus.focus)?tourPrevFocus.focus():0}
$('tourNext').onclick=()=>tourI<TOUR.length-1?tourShow(tourI+1):tourEnd();
$('tourBack').onclick=()=>tourI>0&&tourShow(tourI-1);
