$('tourBtn').onclick=tourStart;$('helpTour').onclick=tourStart;
addEventListener('keydown',e=>{if(tEl.hidden)return;e.stopImmediatePropagation();
  if(e.key==='Escape'){e.preventDefault();tourEnd()}else if(e.key==='ArrowRight'){e.preventDefault();$('tourNext').click()}else if(e.key==='ArrowLeft'){e.preventDefault();$('tourBack').click()}
  else if(e.key==='Tab'){const f=[...tEl.querySelectorAll('button:not(:disabled)')];const a=f.indexOf(document.activeElement);e.preventDefault();f[(a+(e.shiftKey?-1:1)+f.length)%f.length].focus()}},true);
addEventListener('resize',()=>{if(!tEl.hidden)placeSpot()});addEventListener('scroll',()=>{if(!tEl.hidden)placeSpot()},true);

/* ---------- mounting into the academy router ---------- */
const MOUNT={mastery:'v-mastery',slides:'v-slides',explainers:'v-animations',games:'v-games',tools:'v-tools',cheatsheet:'v-cheatsheet',hebrew:'v-hebrew',notes:'v-lab',docs:'v-notes',fixes:'v-fixes',help:'v-help'};
const visited=new Set(S.get('visited',[]));
let mounted=null;
window.ICHUD_PAGES=Object.fromEntries(Object.keys(MOUNT).map(p=>[p,()=>`<div id="ichud-mount"></div>`]));
window.ICHUD_TITLES=PAGE_NAMES;
window.ICHUD_BEFORE=()=>{if(mounted){holder.appendChild(mounted);mounted=null}};
window.ICHUD_AFTER=(page,id)=>{
  if(!visited.has(page)){visited.add(page);S.set('visited',[...visited]);addXP(5)}
  if(page!=='notes'&&focusOpen)closeFocus();
  const m=document.getElementById('ichud-mount');if(!m||!MOUNT[page])return;
  const sec=$(MOUNT[page]);m.replaceWith(sec);mounted=sec;
  if(page==='slides'){renderSlides()}
  if(page==='mastery')renderMastery();
  if(page==='explainers')drawTri();
  if(page==='hebrew'){let q='';try{q=decodeURIComponent(id||'')}catch(e){q=id||''}if(q.startsWith('uh:')){heMode='glossary';heQ=q.slice(3);heCat='all'}else if(q){heMode='course';heCourseQ=q}syncHeModes();heRender()}
  if(page==='notes'&&!pending&&!$('labResult').innerHTML)openFocus();
};
